"use client"

import * as React from "react"
import { ArrowRight } from "lucide-react"

import { cn } from "@/lib/utils"
import { formatNumber, type NumberFormat } from "@/registry/dashboardcn/lib/format"
import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { DeltaBadge, getDeltaDirection } from "@/registry/dashboardcn/ui/delta-badge"
import { PeriodTabs, type PeriodOption } from "@/registry/dashboardcn/ui/period-tabs"
import { Sparkline } from "@/registry/dashboardcn/ui/sparkline"

export interface KpiRowMetric {
  label: string
  value: number | string
  delta?: number
  /** Short word next to the delta, e.g. "Rising". */
  note?: string
  trend?: number[]
  format?: NumberFormat
  currency?: string
  invertDelta?: boolean
  icon?: React.ReactNode
}

export interface KpiRowCardProps extends React.ComponentProps<typeof Card> {
  title: string
  description?: string
  metrics: KpiRowMetric[]
  /** Period options for the switcher. Omit to hide it. */
  periods?: PeriodOption[]
  period?: string
  defaultPeriod?: string
  onPeriodChange?: (period: string) => void
  /** Text in the footer, e.g. a summary sentence. */
  footer?: React.ReactNode
  /** Footer link. */
  action?: { label: string; href: string }
}

/** A card with a row of KPI tiles, each with a sparkline and delta. */
function KpiRowCard({
  title,
  description,
  metrics,
  periods,
  period,
  defaultPeriod,
  onPeriodChange,
  footer,
  action,
  className,
  ...props
}: KpiRowCardProps) {
  return (
    <Card data-slot="kpi-row-card" className={cn("gap-4", className)} {...props}>
      <CardHeader>
        <CardTitle>{title}</CardTitle>
        {description ? <CardDescription>{description}</CardDescription> : null}
        {periods ? (
          <CardAction>
            <PeriodTabs
              options={periods}
              value={period}
              defaultValue={defaultPeriod ?? periods[0]?.value}
              onValueChange={onPeriodChange}
            />
          </CardAction>
        ) : null}
      </CardHeader>
      <CardContent>
        <div className="@container">
          <div className="grid gap-6 @lg:grid-cols-2 @3xl:grid-cols-4 @3xl:divide-x">
            {metrics.map((metric) => {
              const direction = getDeltaDirection(metric.delta)
              const positive =
                direction === "flat"
                  ? null
                  : (direction === "up") !== Boolean(metric.invertDelta)
              const color =
                positive === true
                  ? "var(--color-emerald-500)"
                  : positive === false
                    ? "var(--color-red-500)"
                    : "var(--muted-foreground)"
              const value =
                typeof metric.value === "number"
                  ? formatNumber(metric.value, {
                      format: metric.format,
                      currency: metric.currency,
                    })
                  : metric.value
              return (
                <div
                  key={metric.label}
                  data-slot="kpi-row-metric"
                  className="flex flex-col gap-2 @3xl:px-6 @3xl:first:pl-0 @3xl:last:pr-0"
                >
                  <div className="text-muted-foreground flex items-center gap-1.5 text-sm [&>svg]:size-4">
                    {metric.icon}
                    {metric.label}
                  </div>
                  <div className="flex items-end justify-between gap-3">
                    <div className="flex flex-col gap-1">
                      <span className="text-2xl font-semibold tabular-nums tracking-tight">
                        {value}
                      </span>
                      <span className="flex items-center gap-1.5 text-xs">
                        {metric.delta !== undefined ? (
                          <DeltaBadge
                            delta={metric.delta}
                            invert={metric.invertDelta}
                            variant="soft"
                            showIcon={false}
                          />
                        ) : null}
                        {metric.note ? (
                          <span className="text-muted-foreground">{metric.note}</span>
                        ) : null}
                      </span>
                    </div>
                    {metric.trend && metric.trend.length > 1 ? (
                      <Sparkline
                        data={metric.trend}
                        variant="line"
                        color={color}
                        className="h-9 w-20 shrink-0"
                      />
                    ) : null}
                  </div>
                </div>
              )
            })}
          </div>
        </div>
      </CardContent>
      {footer || action ? (
        <CardFooter className="text-muted-foreground justify-between gap-4 border-t pt-4 text-xs [.border-t]:pt-4">
          <div>{footer}</div>
          {action ? (
            <a
              href={action.href}
              className="text-foreground inline-flex shrink-0 items-center gap-1 font-medium hover:underline"
            >
              {action.label}
              <ArrowRight className="size-3.5" />
            </a>
          ) : null}
        </CardFooter>
      ) : null}
    </Card>
  )
}

export { KpiRowCard }

import * as React from "react"
import { Minus, TrendingDown, TrendingUp } from "lucide-react"

import { cn } from "@/lib/utils"
import { formatDelta } from "@/registry/dashboardcn/lib/format"

export type DeltaDirection = "up" | "down" | "flat"

export function getDeltaDirection(delta: number | undefined): DeltaDirection {
  if (delta === undefined || delta === 0 || !Number.isFinite(delta)) return "flat"
  return delta > 0 ? "up" : "down"
}

const directionIcon: Record<DeltaDirection, React.ElementType> = {
  up: TrendingUp,
  down: TrendingDown,
  flat: Minus,
}

export interface DeltaBadgeProps extends React.ComponentProps<"span"> {
  /** Fractional change, e.g. 0.124 for +12.4%. */
  delta: number
  /** Treat a decrease as good and an increase as bad (churn, latency, errors). */
  invert?: boolean
  variant?: "outline" | "soft" | "text"
  showIcon?: boolean
}

function DeltaBadge({
  delta,
  invert = false,
  variant = "outline",
  showIcon = true,
  className,
  children,
  ...props
}: DeltaBadgeProps) {
  const direction = getDeltaDirection(delta)
  const positive = direction === "flat" ? null : (direction === "up") !== invert
  const Icon = directionIcon[direction]

  return (
    <span
      data-slot="delta-badge"
      data-direction={direction}
      data-positive={positive}
      className={cn(
        "inline-flex items-center gap-1 text-xs font-medium tabular-nums",
        variant === "outline" && "rounded-md border px-1.5 py-0.5",
        variant === "soft" && "rounded-md px-1.5 py-0.5",
        variant === "soft" && positive === true && "bg-emerald-500/10",
        variant === "soft" && positive === false && "bg-red-500/10",
        variant === "soft" && positive === null && "bg-muted",
        positive === true && "text-emerald-600 dark:text-emerald-400",
        positive === false && "text-red-600 dark:text-red-400",
        positive === null && "text-muted-foreground",
        className
      )}
      {...props}
    >
      {showIcon ? <Icon className="size-3" aria-hidden="true" /> : null}
      {children ?? formatDelta(delta)}
    </span>
  )
}

export { DeltaBadge }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs"

export interface PeriodOption {
  value: string
  label: string
}

export const defaultPeriods: PeriodOption[] = [
  { value: "week", label: "Week" },
  { value: "month", label: "Month" },
  { value: "year", label: "Year" },
]

export interface PeriodTabsProps
  extends Omit<React.ComponentProps<typeof Tabs>, "children"> {
  options?: PeriodOption[]
  size?: "sm" | "default"
}

/** Small segmented control for switching a chart's time range. */
function PeriodTabs({
  options = defaultPeriods,
  size = "sm",
  className,
  ...props
}: PeriodTabsProps) {
  return (
    <Tabs data-slot="period-tabs" className={cn("w-fit", className)} {...props}>
      <TabsList className={cn(size === "sm" && "h-7 p-0.5")}>
        {options.map((option) => (
          <TabsTrigger
            key={option.value}
            value={option.value}
            className={cn(size === "sm" && "h-6 px-2.5 text-xs")}
          >
            {option.label}
          </TabsTrigger>
        ))}
      </TabsList>
    </Tabs>
  )
}

export { PeriodTabs }

"use client"

import * as React from "react"
import { Area, AreaChart, Line, LineChart, ResponsiveContainer } from "recharts"

import { cn } from "@/lib/utils"

export interface SparklineProps extends React.ComponentProps<"div"> {
  /** Series to plot, oldest first. */
  data: number[]
  variant?: "area" | "line"
  /** Any CSS color. Defaults to the theme primary. */
  color?: string
  curve?: "monotone" | "linear" | "step"
  strokeWidth?: number
}

function Sparkline({
  data,
  variant = "area",
  color = "var(--primary)",
  curve = "monotone",
  strokeWidth = 1.5,
  className,
  ...props
}: SparklineProps) {
  const id = React.useId()
  const points = React.useMemo(() => data.map((y, i) => ({ i, y })), [data])
  const margin = { top: 2, right: 0, bottom: 0, left: 0 }

  return (
    <div
      data-slot="sparkline"
      aria-hidden="true"
      className={cn("h-10 w-full", className)}
      {...props}
    >
      <ResponsiveContainer width="100%" height="100%">
        {variant === "line" ? (
          <LineChart data={points} margin={margin}>
            <Line
              type={curve}
              dataKey="y"
              stroke={color}
              strokeWidth={strokeWidth}
              dot={false}
              isAnimationActive={false}
            />
          </LineChart>
        ) : (
          <AreaChart data={points} margin={margin}>
            <defs>
              <linearGradient id={id} x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor={color} stopOpacity={0.3} />
                <stop offset="100%" stopColor={color} stopOpacity={0} />
              </linearGradient>
            </defs>
            <Area
              type={curve}
              dataKey="y"
              stroke={color}
              strokeWidth={strokeWidth}
              fill={`url(#${id})`}
              dot={false}
              isAnimationActive={false}
            />
          </AreaChart>
        )}
      </ResponsiveContainer>
    </div>
  )
}

export { Sparkline }

export type NumberFormat = "number" | "compact" | "currency" | "percent"

export interface FormatNumberOptions {
  format?: NumberFormat
  /** ISO 4217 code, used when format is "currency". Defaults to USD. */
  currency?: string
  locale?: string
  maximumFractionDigits?: number
}

const formatterCache = new Map<string, Intl.NumberFormat>()

function getFormatter(locale: string, options: Intl.NumberFormatOptions) {
  const key = locale + JSON.stringify(options)
  let formatter = formatterCache.get(key)
  if (!formatter) {
    formatter = new Intl.NumberFormat(locale, options)
    formatterCache.set(key, formatter)
  }
  return formatter
}

/**
 * Format a metric value for display.
 *
 * formatNumber(1234567)                          -> "1,234,567"
 * formatNumber(1234567, { format: "compact" })   -> "1.2M"
 * formatNumber(48.2, { format: "currency" })     -> "$48.20"
 * formatNumber(0.124, { format: "percent" })     -> "12.4%"
 */
export function formatNumber(
  value: number,
  {
    format = "number",
    currency = "USD",
    locale = "en-US",
    maximumFractionDigits,
  }: FormatNumberOptions = {}
): string {
  if (!Number.isFinite(value)) return "—"

  switch (format) {
    case "compact":
      return getFormatter(locale, {
        notation: "compact",
        maximumFractionDigits: maximumFractionDigits ?? 1,
      }).format(value)
    case "currency":
      return getFormatter(locale, {
        style: "currency",
        currency,
        maximumFractionDigits: maximumFractionDigits ?? 2,
      }).format(value)
    case "percent":
      return getFormatter(locale, {
        style: "percent",
        maximumFractionDigits: maximumFractionDigits ?? 1,
      }).format(value)
    default:
      return getFormatter(locale, {
        maximumFractionDigits: maximumFractionDigits ?? 0,
      }).format(value)
  }
}

/**
 * Format a fractional change as a signed percentage.
 *
 * formatDelta(0.124)  -> "+12.4%"
 * formatDelta(-0.03)  -> "-3.0%"
 * formatDelta(0)      -> "0.0%"
 */
export function formatDelta(delta: number, locale = "en-US"): string {
  if (!Number.isFinite(delta)) return "—"
  return getFormatter(locale, {
    style: "percent",
    signDisplay: "exceptZero",
    maximumFractionDigits: 1,
    minimumFractionDigits: 1,
  }).format(delta)
}

/**
 * Fractional change between two values. Returns 0 when there is no baseline.
 */
export function computeDelta(current: number, previous: number): number {
  if (!previous) return 0
  return (current - previous) / Math.abs(previous)
}
